<main class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
  <div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">Security history</p><h1 class="mt-2 text-3xl font-black">Audit log</h1><p class="mt-2 text-sm text-slate-400">Administrative changes, result corrections, wallet actions and payout decisions.</p></div>
  <form method="get" class="glass-card mt-5 flex flex-wrap items-end gap-3 rounded-2xl p-4"><input type="hidden" name="page" value="admin-audit"><label class="min-w-48 flex-1 text-xs font-bold text-slate-400">Search action or record<input class="form-control mt-2" name="q" maxlength="80" value="<?= h($search) ?>" placeholder="result.corrected"></label><label class="min-w-36 text-xs font-bold text-slate-400">Entity<select class="form-control mt-2" name="entity"><option value="all">All entities</option><?php foreach($entityTypes as $type): ?><option value="<?= h($type) ?>" <?= $entityFilter===$type?'selected':'' ?>><?= h($type) ?></option><?php endforeach; ?></select></label><button class="btn-primary rounded-xl px-5 py-3 text-sm font-black">Filter</button></form>
  <div class="glass-card mt-5 overflow-hidden rounded-2xl"><?php if(!$logs): ?><p class="p-10 text-center text-sm text-slate-500">No audit events found.</p><?php else: ?><div class="table-wrap"><table class="w-full text-left text-xs"><thead class="bg-black/20 text-[10px] uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-4">Time</th><th class="px-4 py-4">Actor</th><th class="px-4 py-4">Action</th><th class="px-4 py-4">Entity</th><th class="px-4 py-4">Change summary</th></tr></thead><tbody class="divide-y divide-white/[.07]"><?php foreach($logs as $item): ?><tr><td class="px-4 py-4 text-[10px] text-slate-500"><?= h(date('d M Y · g:i:s A',strtotime((string)$item['created_at'].' UTC'))) ?></td><td class="px-4 py-4"><?= h($item['email'] ?: 'system') ?></td><td class="px-4 py-4 font-bold"><?= h($item['action']) ?></td><td class="px-4 py-4 text-slate-400"><?= h($item['entity_type']) ?> #<?= h($item['entity_id'] ?? '—') ?></td><td class="px-4 py-4 text-[10px] text-slate-500"><?php if($item['before_data']): ?><span class="block">Before: <?= h(mb_substr(json_encode(json_decode($item['before_data'],true)),0,140)) ?></span><?php endif; ?><?php if($item['after_data']): ?><span class="mt-1 block">After: <?= h(mb_substr(json_encode(json_decode($item['after_data'],true)),0,180)) ?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
  <?php if($pageCount>1): ?><nav class="mt-5 flex gap-2"><?php for($n=1;$n<=$pageCount;$n++): ?><a class="rounded-lg border px-3 py-2 text-xs <?= $n===$pageNumber?'border-violet-400/50 text-violet-200':'border-white/10 text-slate-400' ?>" href="<?= h(app_url('index.php?'.http_build_query(['page'=>'admin-audit','q'=>$search,'entity'=>$entityFilter,'p'=>$n]))) ?>"><?= h($n) ?></a><?php endfor; ?></nav><?php endif; ?>
</main>
